
// Base64 encoded audio data. Sourced from free, 8-bit sound effect libraries.
const audioSources: Record<string, string> = {
    background: 'data:audio/mpeg;base64,----PMkF',
    jump: 'data:audio/wav;base64,',
  coin: 'data:audio/wav;base64, AVQBTAEwASAA/ADgAMwAuACsAJwAjAB8AHAAZABQAEgAQAA0ACgAHAAQAAgABAAAAAAD/AP8A/wD/AP8A/wD/AP8A/wD/AP8A/wD/AP8A',
  stomp: 'data:audio/wav;base64,',
  gameOver: 'data:audio/mpeg;base64,------PMkF',
  stageClear: 'data:audio/mpeg;base64,------PMkF',
};

class AudioService {
  private audioContext: AudioContext;
  private sounds: Record<string, HTMLAudioElement> = {};

  constructor() {
    this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.loadSounds();
  }

  private loadSounds() {
    for (const key in audioSources) {
      const audio = new Audio(audioSources[key]);
      audio.preload = 'auto';
      this.sounds[key] = audio;
    }
  }

  play(soundName: string, loop = false) {
    // Ensure we have a fresh audio context
    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }
    
    const sound = this.sounds[soundName];
    if (sound) {
      sound.loop = loop;
      // If sound is already playing, restart it for crisp sound effects
      if (!sound.paused) {
        sound.currentTime = 0;
      } else {
         sound.currentTime = 0;
      }
      sound.play().catch(error => console.error(`Audio play failed for ${soundName}:`, error));
    }
  }

  stop(soundName: string) {
    const sound = this.sounds[soundName];
    if (sound) {
      sound.pause();
      sound.currentTime = 0;
    }
  }
  
  stopAll() {
    for(const key in this.sounds) {
        this.stop(key);
    }
  }
}

export const audioService = new AudioService();
